def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after '+')
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split off pre-release (after '-')
        if '-' in v:
            version_part, prerelease = v.split('-', 1)
        else:
            version_part = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
            # Convert each identifier to a sortable form
            parsed_prerelease = []
            for part in prerelease_parts:
                if part.isdigit():
                    # All-digit identifier: store as (0, numeric_value)
                    parsed_prerelease.append((0, int(part)))
                else:
                    # Non-digit identifier: store as (1, string_value)
                    parsed_prerelease.append((1, part))
            prerelease_tuple = tuple(parsed_prerelease)
        else:
            # No pre-release: use a tuple that sorts after any pre-release
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    # Create list of (sort_key, original_index, original_version)
    indexed_versions = []
    for i, v in enumerate(versions):
        parsed = parse_version(v)
        # For sorting: (major, minor, patch, prerelease_tuple or special value)
        # None should sort after any pre-release, so we use a special tuple
        if parsed[3] is None:
            sort_key = (parsed[0], parsed[1], parsed[2], (2,))  # (2,) sorts after all pre-releases
        else:
            sort_key = (parsed[0], parsed[1], parsed[2], (1,) + parsed[3])  # (1,) + prerelease_tuple
        indexed_versions.append((sort_key, i, v))

    # Sort by sort_key first, then by original index for stability
    indexed_versions.sort(key=lambda x: (x[0], x[1]))

    # Return just the version strings
    return [v for _, _, v in indexed_versions]

